/*
    GISInfo - جدول دمو جهت تست (نسخهء کامل و مفصل)
    ===================================================
    این اسکریپت به‌جای ویوی واقعی GISInfo (که فعلاً در دسترس نیست) یک جدول با همان نام و
    همان ستون‌هایی می‌سازد که در کد پروژه به آن‌ها ارجاع داده شده، تا همهٔ کوئری‌های
    "SELECT * FROM GISInfo" موجود در پروژه (Helper/ClsHelpper.cs و
    Layouts/Sazmanyar.GIS/ApplicationPage_FetchingData.aspx.cs) و همهٔ فیلدهایی که در
    فایل‌های ShowAllKoridorInfoUserControl*.ascx از نتیجهء AJAX خوانده می‌شوند
    (ObjAllRoutInfo.X / result[i].X) بدون تغییر کار کنند.

    مشخص شد GISInfo صرفاً یک ویوی نقشه‌ای ساده نیست؛ به یک سامانهء مدیریت پروژهء مخابراتی/EPM
    هم وصل بوده (فیلدهای ProjectUID، تاریخ‌های شروع/پایان برنامه‌ای و واقعی، درصد پیشرفت، و
    گروهی از فیلدهای تخصصی که فقط بسته به مقدار ستون ProgramType نمایش داده می‌شوند: فیبر /
    رادیویی / دیتا و سوئیچ / مالتی‌پلکس).

    وضعیت هر ستون:
      [CONFIRMED]  - مستقیماً در کد به این اسم دقیق ارجاع داده شده (WHERE، یا .PropertyName در JS)
      [INFERRED]   - در کد فعلی مستقیم استفاده نشده، ولی بر اساس تقارن StationFrom_* / StationTo_*
                     (که برای Tahaghogh و ID و Title قطعی است) به احتمال زیاد وجود دارد
      [PK]         - کلید اصلی که خودم برای یکتایی سطرها اضافه کردم (چون در کد به اسم خاصی
                     برایش ارجاع نشده، فقط ObjAllRoutInfo.ID که همان معنی را می‌رساند)

    توجه: این فقط برای دمو/تست محلی است. وقتی ویوی واقعی GISInfo در دسترس قرار گرفت،
    کافی‌ست این جدول DROP شود و به‌جایش از همان ویو استفاده شود؛ کد فقط اسم "GISInfo" را
    می‌بیند، چه View باشد چه Table.
*/

USE Samix2013;  -- نام دیتابیس را در صورت نیاز با نام واقعی خودتان جایگزین کنید
GO

IF OBJECT_ID('dbo.GISInfo', 'U') IS NOT NULL
    DROP TABLE dbo.GISInfo;
GO

CREATE TABLE dbo.GISInfo
(
    ------------------------------------------------------------------
    -- هویت / هندسهء مسیر
    ------------------------------------------------------------------
    ID                          INT IDENTITY(1,1) PRIMARY KEY,   -- [CONFIRMED] result[i].ID / ObjAllRoutInfo.ID
    Title                       NVARCHAR(200)   NULL,            -- [CONFIRMED] عنوان مسیر، LIKE N'%...%'
    Color                       NVARCHAR(20)    NULL,            -- [CONFIRMED] ObjAllRoutInfo.Color -> رنگ کل مسیر روی نقشه
    FillColor                   NVARCHAR(50)    NULL,            -- [CONFIRMED] رنگ داخل سطح (چندضلعی)؛ خالی = Color
    BorderColor                 NVARCHAR(50)    NULL,            -- [CONFIRMED] رنگ دور سطح؛ خالی = Color
    Opacity                     FLOAT           NULL,            -- [CONFIRMED] شفافیت داخل سطح 0 تا 1؛ خالی = 0.35 (اسلایدر «شفافیت سطح‌ها» روی همه اولویت دارد)
    Points                      NVARCHAR(MAX)   NULL,            -- [CONFIRMED] JSON نقاط مسیر: [{"lat":..,"lng":..}, ...]
    URLInfo                     NVARCHAR(400)   NULL,            -- [CONFIRMED] لینک جزئیات مسیر

    LatFrom                     FLOAT           NULL,            -- [CONFIRMED]
    LongFrom                    FLOAT           NULL,            -- [CONFIRMED]
    LatTo                       FLOAT           NULL,            -- [CONFIRMED]
    LongTo                      FLOAT           NULL,            -- [CONFIRMED]

    ------------------------------------------------------------------
    -- ارتباط با ایستگاه‌ها
    ------------------------------------------------------------------
    StationFrom_ID              INT             NULL,            -- [CONFIRMED]
    StationTo_ID                INT             NULL,            -- [CONFIRMED]
    StationFrom_Title           NVARCHAR(200)   NULL,            -- [CONFIRMED]
    StationTo_Title             NVARCHAR(200)   NULL,            -- [CONFIRMED]
    StationID                   INT             NULL,            -- [CONFIRMED] برای لینک جزئیات یک ایستگاه به‌تنهایی

    ------------------------------------------------------------------
    -- دسته‌بندی / فیلتر
    ------------------------------------------------------------------
    ProgramName                 NVARCHAR(200)   NULL,            -- [CONFIRMED] IN (N'...')
    Department                  NVARCHAR(200)   NULL,            -- [CONFIRMED] فیلتر دپارتمان (نسخهء AbOBargh)
    ProgramType                 NVARCHAR(50)    NULL,            -- [CONFIRMED] 'فیبر' | 'رادیویی' | 'دیتا و سوئیج' | 'مالتی پلکس'
    TahaghoghRoute               INT             NULL,           -- [CONFIRMED] دستهء تحقق مسیر/سطح؛ همان id گزینه‌های DarsadValue در فیلترها:
                                                                 --   1 = بیش از ۹۰٪ (سبز)   2 = ۷۰ تا ۹۰٪ (زرد)   3 = ۵۰ تا ۷۰٪ (صورتی)
                                                                 --   4 = کمتر از ۵۰٪ (قرمز)   5 = آغاز نشده
    StationFrom_Tahaghogh       INT             NULL,            -- [CONFIRMED] دستهء تحقق ایستگاه مبدا (همان کدها)
    StationTo_Tahaghogh         INT             NULL,            -- [CONFIRMED] دستهء تحقق ایستگاه مقصد (همان کدها)

    ------------------------------------------------------------------
    -- پیشرفت / تحقق (سطح مسیر)
    ------------------------------------------------------------------
    RoutePlan                   NVARCHAR(20)    NULL,            -- [CONFIRMED] درصد پیشرفت برنامه‌ای
    RouteActual                 NVARCHAR(20)    NULL,            -- [CONFIRMED] درصد پیشرفت واقعی
    PercentTahaghoghRoute       NVARCHAR(20)    NULL,            -- [CONFIRMED] درصد تحقق
    Complete                    NVARCHAR(20)    NULL,            -- [CONFIRMED] درصد پیشرفت (نسخهء Tajamoee/NewTajamoee)

    ------------------------------------------------------------------
    -- تاریخ‌های مدیریت پروژه (سطح مسیر)
    ------------------------------------------------------------------
    RouteStartDate               DATETIME        NULL,           -- [CONFIRMED]
    RouteFinishDate               DATETIME        NULL,          -- [CONFIRMED]
    RouteBaselineStartDate       DATETIME        NULL,           -- [CONFIRMED]
    RouteBaselineFinishDate      DATETIME        NULL,           -- [CONFIRMED]
    RouteActualStartDate         DATETIME        NULL,           -- [CONFIRMED]
    RouteActualFinishDate        DATETIME        NULL,           -- [CONFIRMED]

    ------------------------------------------------------------------
    -- اتصال به سامانهء مدیریت پروژه (EPM)
    ------------------------------------------------------------------
    ProjectUID                   NVARCHAR(100)   NULL,           -- [CONFIRMED] در URL گزارش‌ها
    RouteID                      NVARCHAR(50)    NULL,           -- [CONFIRMED] در URL گزارش‌ها

    ------------------------------------------------------------------
    -- فیلدهای تخصصی مخابراتی (فقط وقتی ProgramType = 'فیبر')
    ------------------------------------------------------------------
    FibrLongRoute                NVARCHAR(50)    NULL,           -- [CONFIRMED] طول مسیر
    TypeCable                    NVARCHAR(100)   NULL,           -- [CONFIRMED] نوع کابل
    FibrCountCable                NVARCHAR(20)    NULL,          -- [CONFIRMED] تعداد کابل
    FibrTypeRoute                 NVARCHAR(100)   NULL,          -- [CONFIRMED] نوع مسیر

    ------------------------------------------------------------------
    -- فیلدهای تخصصی مخابراتی (فقط وقتی ProgramType = 'رادیویی')
    ------------------------------------------------------------------
    RadioStationNetWork          NVARCHAR(100)   NULL,           -- [CONFIRMED] مدیریت شبکه
    RadioStationRadio            NVARCHAR(100)   NULL,           -- [CONFIRMED] رادیو
    RadioStationPower            NVARCHAR(100)   NULL,           -- [CONFIRMED] تغذیه نیرو
    RadioStationTower            NVARCHAR(100)   NULL,           -- [CONFIRMED] دکل
    RadioRouteFiber               NVARCHAR(100)   NULL,          -- [CONFIRMED] فیبر
    RadioRouteLineTerminal        NVARCHAR(100)   NULL,          -- [CONFIRMED] لاین ترمینال
    RadioRouteRadio                NVARCHAR(100)   NULL,         -- [CONFIRMED] رادیو مسیر

    ------------------------------------------------------------------
    -- فیلدهای تخصصی مخابراتی (فقط وقتی ProgramType = 'دیتا و سوئیج')
    ------------------------------------------------------------------
    SwitchTypeEquipment           NVARCHAR(100)   NULL,          -- [CONFIRMED] نوع تجهیزات
    SwitchCountLink                NVARCHAR(20)    NULL,         -- [CONFIRMED] تعداد لینک
    SwitchBandwidth                 NVARCHAR(50)    NULL,        -- [CONFIRMED] پهنای باند واگذارشده
    SwitchInternetCapacity           NVARCHAR(50)    NULL,       -- [CONFIRMED] ظرفیت اینترنت واگذارشده
    SwitchCountPortAccess             NVARCHAR(20)    NULL,      -- [CONFIRMED] تعداد پورت دسترسی
    SwitchCountPortAssignment          NVARCHAR(20)    NULL,     -- [CONFIRMED] تعداد پورت قابل واگذاری
    SwitchBlankSlot                     NVARCHAR(20)    NULL,    -- [CONFIRMED] تعداد اسلات خالی
    SwitchInterface                      NVARCHAR(20)    NULL,   -- [CONFIRMED] تعداد اینترفیس خالی

    ------------------------------------------------------------------
    -- فیلدهای تخصصی مخابراتی (فقط وقتی ProgramType = 'مالتی پلکس')
    ------------------------------------------------------------------
    MultiplexLinkCapacity          NVARCHAR(50)    NULL,         -- [CONFIRMED] ظرفیت لینک
    MultiplexWeakeningLink          NVARCHAR(50)    NULL,        -- [CONFIRMED] تضعیف لینک
    MultiplexDistance                NVARCHAR(50)    NULL,       -- [CONFIRMED] مسافت
    MultiplexCableAttenuation         NVARCHAR(50)    NULL,      -- [CONFIRMED] تضعیف کابل
    MultiplexCountLynda                 NVARCHAR(20)    NULL,    -- [CONFIRMED] تعداد لاندا
    MultiplexTypeStation                 NVARCHAR(100)   NULL,   -- [CONFIRMED] نوع ایستگاه

    ------------------------------------------------------------------
    -- فیلدهای قدیمی/فعلاً کامنت‌شده در UI (هنوز در کد ارجاع دارند)
    ------------------------------------------------------------------
    NumberCore                    NVARCHAR(20)    NULL,          -- [CONFIRMED] تعداد کر
    PlaneDistanceMap               FLOAT           NULL,         -- [CONFIRMED] طول مسیر هوایی
    PlaneDistanceChart              FLOAT           NULL,        -- [CONFIRMED] طول مسیر جغرافیایی
    ReduceCore1                      FLOAT           NULL,       -- [CONFIRMED] میزان افت کر اول
    ReduceCore2                       FLOAT           NULL,      -- [CONFIRMED] میزان افت کر دوم

    ------------------------------------------------------------------
    -- جزئیات مدیریت‌پروژه‌ای ایستگاه مبدا
    ------------------------------------------------------------------
    StationFrom_OwnerShip          NVARCHAR(100)   NULL,         -- [CONFIRMED] مالکیت
    StationFrom_PlanPercent         NVARCHAR(20)    NULL,        -- [CONFIRMED] درصد پیشرفت برنامه‌ای
    StationFrom_ActualPercent        NVARCHAR(20)    NULL,       -- [CONFIRMED] درصد پیشرفت واقعی
    StationFrom_StartDate             DATETIME        NULL,      -- [CONFIRMED]
    StationFrom_FinishDate             DATETIME        NULL,     -- [CONFIRMED]
    StationFrom_BaselineStartDate       DATETIME        NULL,    -- [CONFIRMED]
    StationFrom_BaselineFinishDate       DATETIME        NULL,   -- [CONFIRMED]
    StationFrom_Duration                  NVARCHAR(20)    NULL,  -- [CONFIRMED] مدت زمان
    StationFrom_DurationVariance           NVARCHAR(20)    NULL, -- [CONFIRMED] انحراف مدت زمان
    StationFrom_CostVariance                NVARCHAR(20)    NULL,-- [CONFIRMED] انحراف هزینه
    StationFrom_PercentTahaghogh             NVARCHAR(20)    NULL, -- [CONFIRMED] درصد تحقق

    ------------------------------------------------------------------
    -- جزئیات مدیریت‌پروژه‌ای ایستگاه مقصد
    -- [INFERRED] در UI فعلی خوانده نمی‌شوند، ولی چون StationFrom/StationTo همیشه به‌صورت
    -- جفت متقارن در بقیهء view دیده شده (ID، Title، Tahaghogh)، احتمال زیاد این ستون‌ها هم
    -- در ویوی اصلی وجود دارند؛ اگر مطمئن نیستید می‌توانید این بخش را حذف کنید.
    ------------------------------------------------------------------
    StationTo_OwnerShip            NVARCHAR(100)   NULL,         -- [INFERRED]
    StationTo_PlanPercent           NVARCHAR(20)    NULL,        -- [INFERRED]
    StationTo_ActualPercent          NVARCHAR(20)    NULL,       -- [INFERRED]
    StationTo_StartDate               DATETIME        NULL,      -- [INFERRED]
    StationTo_FinishDate               DATETIME        NULL,     -- [INFERRED]
    StationTo_BaselineStartDate         DATETIME        NULL,    -- [INFERRED]
    StationTo_BaselineFinishDate         DATETIME        NULL,   -- [INFERRED]
    StationTo_Duration                    NVARCHAR(20)    NULL,  -- [INFERRED]
    StationTo_DurationVariance             NVARCHAR(20)    NULL, -- [INFERRED]
    StationTo_CostVariance                  NVARCHAR(20)    NULL,-- [INFERRED]
    StationTo_PercentTahaghogh               NVARCHAR(20)    NULL, -- [INFERRED]

    ------------------------------------------------------------------
    -- ستون‌هایی که فقط صفحات جستجو (Layouts/Sazmanyar.GIS/Filter/js/demo_widgets*.js)
    -- در شرط WHERE به آن‌ها ارجاع می‌دهند. در UI نمایش داده نمی‌شوند، ولی بدون آن‌ها
    -- هر جستجویی که یکی از این فیلدها را داشته باشد با خطای SQL بی‌نتیجه می‌ماند
    -- (کد C# خطا را می‌بلعد و فقط لیست خالی برمی‌گرداند).
    ------------------------------------------------------------------
    Holding                       NVARCHAR(200)   NULL,          -- [FILTER] هلدینگ (ایستگاه / مسیر / سطح)
    ProjectStatus                 NVARCHAR(100)   NULL,          -- [FILTER] وضعیت پروژه
    Province                      NVARCHAR(100)   NULL,          -- [FILTER] استان (مسیر / سطح)
    RoutePhase                    NVARCHAR(100)   NULL,          -- [FILTER] فاز - اولویت (مسیر / سطح)
    RouteDurationVariance         FLOAT           NULL,          -- [FILTER] انحراف مدت زمان مسیر / سطح
    RouteSPI                      FLOAT           NULL,          -- [FILTER] وضعیت زمان مسیر / سطح
    RouteCPI                      FLOAT           NULL,          -- [FILTER] وضعیت هزینه مسیر / سطح
    StationFrom_SPI               FLOAT           NULL,          -- [FILTER] وضعیت زمان ایستگاه
    StationFrom_CPI               FLOAT           NULL,          -- [FILTER] وضعیت هزینه ایستگاه

    -- نام‌های دیگری که فیلترها برای همان ستون‌های بالا به کار می‌برند (ستون محاسباتی، بدون تکرار داده)
    ProjectType                   AS ProgramType,                                   -- [FILTER] «نوع پروژه» در هر سه فیلتر
    ProectStatus                  AS ProjectStatus,                                 -- [FILTER] غلط املایی موجود در demo_widgetsSath.js
    PlanPercentCompleteRoute      AS TRY_CONVERT(INT, RoutePlan),                   -- [FILTER] پیشرفت برنامه‌ای مسیر / سطح
    PercentCompleteRoute          AS TRY_CONVERT(INT, RouteActual),                 -- [FILTER] پیشرفت واقعی مسیر / سطح
    StationFrom_PercentCompleted  AS TRY_CONVERT(INT, StationFrom_ActualPercent)    -- [CONFIRMED] ForShowIframInfo.htm (درصد پیشرفت ایستگاه) + فیلتر ایستگاه
);
GO

/* ==================================================================
   داده‌های تستی واقعی: مسیر بین هر ۴۵ جفت از ۱۰ ایستگاه واقعی سایت
   (لیست «ایستگاه ها»، مختصات دقیقاً از همان لیست گرفته شده)

   نقاط هر Points با فراخوانی واقعی موتور مسیریابی OSRM (همان موتوری که در کنترل
   ShowAllKoridorInfoUserControl_adminLeaflet با Leaflet Routing Machine استفاده
   می‌شود) بین مختصات هر جفت ایستگاه محاسبه شده - یعنی مسیر واقعی روی جاده است،
   نه خط مستقیم. فاصله/مدت (که در فیلدهای FibrLongRoute/MultiplexDistance
   استفاده شده) هم از همان پاسخ واقعی OSRM است.

   بقیهء فیلدها (رنگ، دپارتمان، نوع پروژه، تاریخ‌ها، درصد پیشرفت، و فیلدهای
   تخصصی هر ProgramType) به‌صورت چرخشی و تعیین‌شده پر شده‌اند تا هیچ ستونی
   NULL نماند؛ فیلدهای تخصصی هر خانواده (فیبر/رادیویی/سوییچ/مالتی‌پلکس) فقط
   برای همان ردیف‌هایی مقدار دارند که ProgramType‌شان با آن خانواده یکی است -
   بقیه NULL می‌مانند چون از نظر مفهومی به آن ردیف مربوط نیستند.

   سه نوع ردیف در این جدول وجود دارد و کد نمایش (ShowAllKoridorInfoUserControl_View*.ascx و
   FetchAbstractInfoFromDataBase_New در ApplicationPage_FetchingData.aspx.cs) فقط از روی
   ترکیب NULL بودن ستون‌ها نوع هر ردیف را تشخیص می‌دهد:

     مسیر  (polyline): Points پر + LatFrom/LongFrom + LatTo/LongTo + StationTo_Title پر
     سطح   (polygon) : Points پر (حلقهٔ بستهٔ چندضلعی؛ نقطهٔ آخر را خودِ JS تکرار می‌کند)
                       و LatFrom/LongFrom/LatTo/LongTo/StationTo_Title همگی NULL
                       (در JS: points.length > 0 && LatFrom == 0 && LongFrom == 0)
     ایستگاه (marker) : Points NULL و LatFrom/LongFrom پر؛ Title باید NULL باشد چون
                       فیلتر «ایستگاه» شرط  ( ... ) and ( Title is null )  را اضافه می‌کند،
                       و StationFrom_ID/StationID همان شناسهٔ ایستگاه است
                       (FetchAllCoridorInfoFromDataBase_ByStation_ID: StationFrom_ID = X and Points is null)

   ردیف‌های مسیر (۴۵ ردیف بعدی) در بخش ۱، ایستگاه‌ها (۱۰ ردیف) در بخش ۲ و سطح‌ها (۵ ردیف) در بخش ۳ درج می‌شوند.
   ================================================================== */

/* ---------- بخش ۱: مسیرها ---------- */

