/* ---------- بخش ۴: پر کردن ستون‌های [FILTER] برای ۴۵ ردیف مسیر (تا فیلترهای جستجو روی مسیرها هم نتیجه بدهند) ---------- */
UPDATE dbo.GISInfo
SET Holding = CASE Department WHEN N'آب و برق' THEN N'هلدینگ انرژی' WHEN N'بنیاد' THEN N'هلدینگ عمران' ELSE N'هلدینگ ارتباطات' END,
    ProjectStatus = CASE WHEN TRY_CONVERT(INT, RouteActual) >= 100 THEN N'خاتمه یافته'
                         WHEN ISNULL(TRY_CONVERT(INT, RouteActual), 0) = 0 THEN N'آغاز نشده'
                         ELSE N'در حال اجرا' END,
    Province = CASE StationFrom_ID
                   WHEN 1 THEN N'تهران' WHEN 2 THEN N'مرکزی' WHEN 3 THEN N'قزوین' WHEN 4 THEN N'مازندران' WHEN 5 THEN N'قم'
                   WHEN 6 THEN N'مرکزی' WHEN 7 THEN N'همدان' WHEN 8 THEN N'زنجان' WHEN 9 THEN N'همدان' ELSE N'همدان' END,
    RoutePhase = CASE ID % 3 WHEN 0 THEN N'فاز 1 - اولویت بالا' WHEN 1 THEN N'فاز 2 - اولویت متوسط' ELSE N'فاز 3 - اولویت پایین' END,
    RouteDurationVariance = TRY_CONVERT(FLOAT, LEFT(StationFrom_DurationVariance, CHARINDEX(' ', StationFrom_DurationVariance + ' ') - 1)),
    RouteSPI = ROUND(TRY_CONVERT(FLOAT, RouteActual) / NULLIF(TRY_CONVERT(FLOAT, RoutePlan), 0), 2),
    RouteCPI = ROUND(1 + ((ID % 7) - 3) / 100.0, 2),
    StationFrom_SPI = ROUND(TRY_CONVERT(FLOAT, StationFrom_ActualPercent) / NULLIF(TRY_CONVERT(FLOAT, StationFrom_PlanPercent), 0), 2),
    StationFrom_CPI = ROUND(1 + ((ID % 5) - 2) / 100.0, 2)
WHERE Points IS NOT NULL AND LatFrom IS NOT NULL AND LatTo IS NOT NULL;

GO

SELECT COUNT(*) AS TotalRows,
       SUM(CASE WHEN Points IS NOT NULL AND LatFrom IS NOT NULL THEN 1 ELSE 0 END) AS Routes,
       SUM(CASE WHEN Points IS NOT NULL AND LatFrom IS NULL     THEN 1 ELSE 0 END) AS Areas,
       SUM(CASE WHEN Points IS NULL     AND LatFrom IS NOT NULL THEN 1 ELSE 0 END) AS Stations
FROM dbo.GISInfo;
SELECT * FROM dbo.GISInfo ORDER BY ID;
GO
